style:
/* 汐岸 —— 浅蓝通栏页眉，左侧蓝色窄栏排成白卡，主栏挂点线导轨 */

.tw-xian.layout-sidebar.resume-paper.layout-sidebar {
  padding-top: 0;
}

.tw-xian.layout-sidebar.resume-paper .paper-header {
  margin: 0 -15mm 6mm;
  padding: 10mm 15mm 6mm;
  background: #e3ecf2;
  border: none;
  color: #23323c;
  align-items: center;
  gap: 7mm;
  print-color-adjust: exact;
}

.tw-xian.layout-sidebar.resume-paper .paper-photo {
  order: -1;
  width: 25mm;
  height: 33mm;
  border: 1.2mm solid #fff;
  border-radius: 0;
  box-shadow: 0 0 0 0.3mm #c9d9e3;
}

.tw-xian.layout-sidebar.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #fff;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-xian.layout-sidebar.resume-paper .paper-name {
  color: #1d2c36;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.1);
  letter-spacing: 0.06em;
}

.tw-xian.layout-sidebar.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #5c707c;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-xian.layout-sidebar.resume-paper .paper-role {
  margin-top: 1.8mm;
  color: #3d5461;
  font-size: calc(var(--paper-base-size) * 0.94);
  font-weight: 400;
}

.tw-xian.layout-sidebar.resume-paper .paper-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4mm 7mm;
  margin-top: 3mm;
  color: #3a4e5a;
  font-size: calc(var(--paper-base-size) * 0.85);
}

.tw-xian.layout-sidebar.resume-paper .paper-contact {
  display: inline-flex;
  gap: 1.4mm;
}

.tw-xian.layout-sidebar.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-xian.layout-sidebar.resume-paper .paper-contact__label {
  color: #7b8f9b;
}

/* 窄栏：浅蓝底、白卡分区 */
.tw-xian.layout-sidebar.resume-paper .sidebar-layout {
  grid-template-columns: 54mm minmax(0, 1fr);
  column-gap: 11mm;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-aside {
  grid-column: 1;
  padding: 4mm 3.4mm;
  background: #e9f0f5;
  border-top: none;
  border-radius: 1.6mm;
  print-color-adjust: exact;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-main {
  grid-column: 2;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-aside .paper-section {
  margin-top: 0;
  margin-bottom: 3mm;
  padding: 3mm 3mm 2.6mm;
  background: #fff;
  border-radius: 1.2mm;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-aside .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2mm;
  margin-bottom: 2.4mm;
  padding-bottom: 1mm;
  border-bottom: 0.25mm solid #e2ebf1;
  color: #2b4351;
  font-size: calc(var(--paper-base-size) * 0.94);
  letter-spacing: 0.08em;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-aside .paper-section__icon {
  display: grid;
  place-items: center;
  width: 4mm;
  height: 4mm;
  color: var(--paper-accent);
}

.tw-xian.layout-sidebar.resume-paper .sidebar-aside .paper-section__icon svg {
  width: 100%;
  height: 100%;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-main .paper-section {
  position: relative;
  padding-left: 5.5mm;
  border-left: 0.22mm dotted #c2d5e0;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-main .paper-section__title {
  position: relative;
  display: flex;
  align-items: center;
  gap: 2.4mm;
  margin-bottom: 2.8mm;
  padding-bottom: 1.2mm;
  border-bottom: 0.25mm solid #e0eaf0;
  color: #243842;
  font-size: calc(var(--paper-base-size) * 1.02);
  letter-spacing: 0.08em;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-main .paper-section__title::before {
  content: "";
  position: absolute;
  top: 0.4mm;
  left: -5.6mm;
  width: 2.4mm;
  height: 2.4mm;
  border-radius: 50%;
  background: var(--paper-accent);
  print-color-adjust: exact;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-main .paper-section__icon {
  display: grid;
  place-items: center;
  width: 4.2mm;
  height: 4.2mm;
  margin-left: auto;
  color: color-mix(in srgb, var(--paper-accent) 62%, #fff);
}

.tw-xian.layout-sidebar.resume-paper .sidebar-main .paper-section__icon svg {
  width: 100%;
  height: 100%;
}

.tw-xian.layout-sidebar.resume-paper .paper-section__body {
  color: #32434d;
}

.tw-xian.layout-sidebar.resume-paper .paper-item-title {
  color: #1d2c36;
}

.tw-xian.layout-sidebar.resume-paper .paper-item-period {
  color: #768894;
  font-size: calc(var(--paper-base-size) * 0.85);
}

.tw-xian.layout-sidebar.resume-paper .paper-item-sub {
  color: #43555f;
}

.tw-xian.layout-sidebar.resume-paper .paper-rich ul,
.tw-xian.layout-sidebar.resume-paper .paper-rich ol {
  margin-top: 0.8mm;
  padding-left: 0;
  list-style: none;
}

.tw-xian.layout-sidebar.resume-paper .paper-rich li {
  position: relative;
  margin: 0.7mm 0;
  padding-left: 3.4mm;
}

.tw-xian.layout-sidebar.resume-paper .paper-rich li::before {
  content: "";
  position: absolute;
  top: 0.7em;
  left: 0.4mm;
  width: 1mm;
  height: 1mm;
  border-radius: 50%;
  background: #9db2bf;
  print-color-adjust: exact;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-aside .paper-skills {
  grid-template-columns: minmax(0, 1fr);
  gap: 1.6mm;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-aside .paper-skill {
  position: relative;
  display: block;
  padding-bottom: 0;
  border-bottom: none;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-aside .paper-skill__name {
  display: flex;
  justify-content: space-between;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-xian.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots {
  display: flex;
  gap: 0;
  margin-top: 0.8mm;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots i {
  width: 8mm;
  height: 1.3mm;
  border-radius: 0;
  background: #e2ebf1;
}

.tw-xian.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots i.filled {
  background: var(--paper-accent);
}

.tw-xian.layout-sidebar.resume-paper .sidebar-aside .paper-skill__level {
  position: absolute;
  top: 0;
  right: 0;
  display: inline;
  color: #5d7482;
  font-size: calc(var(--paper-base-size) * 0.78);
}

.tw-xian.layout-sidebar.resume-paper .paper-note__tag {
  color: #1d2c36;
  font-weight: 600;
}

.tw-xian.layout-sidebar.resume-paper .paper-footer {
  border-top: 0.2mm solid #e3ecf2;
  color: #9fb0bb;
}
